def process(load_mmc1):
    df = load_mmc1.copy()
    serous = df[df['Histologic_type'] == 'Serous'][['idx', 'Case_excluded', 'Log2_variant_per_Mbp', 'Proteomics_Tumor_Normal']].copy()
    serous['variants_per_Mbp'] = 2 ** serous['Log2_variant_per_Mbp']
    return serous.sort_values('idx').reset_index(drop=True)
